/**
 * Recompute directions after a reroute.
 * Mirrors the logic in computeRouteSession but without re-running A*.
 */
function recomputeDirections(
  path: PathResult,
  route: RouteSessionReadyState,
  graph: NormalizedNavGraph,
): DirectionsResult {
  // Import here to avoid circular dependency at module level.
  // eslint-disable-next-line @typescript-eslint/no-use-before-define
  const { generateDirections } = require('../routing/generateDirections') as {
    generateDirections: (nodeIds: string[], nodeMap: Map<string, import('../../src/shared/types').NavNode>, mode: import('../domain/navGraph').RouteMode, floorMap: Map<number, import('../../src/shared/types').NavFloor>) => DirectionsResult;
  };

  const nodeMap = new Map<string, import('../../src/shared/types').NavNode>();
  for (const [id, record] of graph.nodeById) {
    nodeMap.set(id, record.node);
  }

  const floorMap = new Map<number, import('../../src/shared/types').NavFloor>();
  for (const [id, record] of graph.floorById) {
    floorMap.set(id, record.floor);
  }

  return generateDirections(
    path.nodeIds,
    nodeMap,
    route.routeMode,
    floorMap,
  );
}

/**
 * App — visitor navigation runtime (no sign-in required).
 *
 * Composition:
 * - Bootstrap: loads nav graph + campus image from configured endpoints
 * - DestinationPicker: building/floor/node search with start/destination selection
 * - MapViewportFloor: floor plan image viewer + route path overlay + floor switcher
 * - RoutePreview: step-by-step directions when route is ready
 * - Accessible mode toggle: switches between standard / accessible routing
 */

import { useCallback, useEffect, useState } from 'react';
import {
  ActivityIndicator,
  Pressable,
  ScrollView,
  StyleSheet,
  Text,
  View,
} from 'react-native';

import {
  IDLE_MAP_BOOTSTRAP_STATE,
  type MapBootstrapState,
  runMapBootstrap,
} from './bootstrap/mapBootstrapState';
import type { NormalizedNavGraph } from './domain/navGraph';
import { MapViewportFloor } from './map/MapViewportFloor';
import type { FloorPlanTarget } from './data/mapApiClient';
import { createMapApiClient } from './data/mapApiClient';
import {
  createInitialMapTransform,
  mapTransformsEqual,
  type MapTransform,
} from './map/mapTransform';
import { DestinationPicker } from './components/destination/DestinationPicker';
import { RoutePreview } from './components/route/RoutePreview';
import { RoutePathOverlay, type RoutePathPoint } from './components/route/RoutePathOverlay';
import { useRouteSelection } from './hooks/useRouteSelection';
import { useRouteSession } from './routing/useRouteSession';
import { useGuidanceSession } from './hooks/useGuidanceSession';
import { useCurrentPosition } from './hooks/useCurrentPosition';
import { LiveGuidanceOverlay } from './components/guidance/LiveGuidanceOverlay';
