/**
 * Route session state machine — pure computation, no React dependencies.
 *
 * Coordinates pathfinding (T01 engine) and direction generation (T01)
 * into a single discriminated union state that drives the UI.
 */

import type { NavNode } from '../../src/shared/types';
import type {
  DirectionsResult,
  NormalizedNavGraph,
  PathResult,
  RouteMode,
} from '../domain/navGraph';
import { MobilePathfindingEngine } from './pathfindingEngine';
import { generateDirections } from './generateDirections';

// ============================================================
// Phase types
// ============================================================

export type RouteSessionPhase =
  | 'idle'
  | 'computing'
  | 'ready'
  | 'no-route'
  | 'error';

// ============================================================
// Discriminated union state types
// ============================================================

export interface RouteSessionIdleState {
  readonly phase: 'idle';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionComputingState {
  readonly phase: 'computing';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionReadyState {
  readonly phase: 'ready';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: PathResult;
  readonly directions: DirectionsResult;
  readonly errorMessage: null;
}

export interface RouteSessionNoRouteState {
  readonly phase: 'no-route';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: null;
}

export interface RouteSessionErrorState {
  readonly phase: 'error';
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly routeMode: RouteMode;
  readonly path: null;
  readonly directions: null;
  readonly errorMessage: string;
}

/**
 * Discriminated union of all route session states.
 *
 * Discriminant key: `phase`
 *
 * Phase meanings:
 * - `idle`:    No start/destination yet
 * - `computing`: Currently computing (sync, so only an intermediate phase)
 * - `ready`:  Route found — path and directions available
 * - `no-route`: Start & dest selected but no path exists
 * - `error`:  Node not present in graph or other error
 */
export type RouteSessionState =
  | RouteSessionIdleState
  | RouteSessionComputingState
  | RouteSessionReadyState
  | RouteSessionNoRouteState
  | RouteSessionErrorState;

// ============================================================
// Options
// ============================================================

export interface RouteSessionOptions {
  readonly graph: NormalizedNavGraph;
  readonly mode: RouteMode;
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
}

// ============================================================
// Private helpers
// ============================================================

/**
 * Compute directions from a found path result.
 * Uses nodeMap and floorMap from the normalized graph.
 */
function computeDirections(
  path: PathResult,
  mode: RouteMode,
  graph: NormalizedNavGraph,
): DirectionsResult {
  // Extract plain NavNode objects from normalized records
  const nodeMap = new Map<string, NavNode>();
  for (const [id, record] of graph.nodeById) {
    nodeMap.set(id, record.node);
  }

  // Extract plain NavFloor objects from normalized records
  const floorMap = new Map<number, import('../../src/shared/types').NavFloor>();
  for (const [id, record] of graph.floorById) {
    floorMap.set(id, record.floor);
  }

  return generateDirections(
    path.nodeIds,
    nodeMap,
    mode,
    floorMap,
  );
}

// ============================================================
// Main computation function
// ============================================================

/**
 * Compute a route session state synchronously.
 *
 * A* is fast enough that no async boundary is needed.
 * The 'computing' phase is included for UI tooling (DevTools)
 * and to make the phase model complete.
 *
 * Transitions:
 * - start === null || destination === null → 'idle'
 * - start/dest valid but not in graph         → 'error'
 * - start/dest in graph, no path found        → 'no-route'
 * - start/dest in graph, path found           → 'ready'
 */
export function computeRouteSession(options: RouteSessionOptions): RouteSessionState {
  const { graph, mode, start, destination } = options;

  // Guard: missing input
  if (start === null || destination === null) {
    return {
      phase: 'idle',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Guard: nodes not in graph
  if (!graph.nodeById.has(start.id) || !graph.nodeById.has(destination.id)) {
    return {
      phase: 'error',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: 'One or both selected nodes are not present in the navigation graph.',
    };
  }

  // Guard: start === destination
  if (start.id === destination.id) {
    return {
      phase: 'idle',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Compute path
  const engine = new MobilePathfindingEngine(graph);
  const path = engine.findRoute(start.id, destination.id, mode);

  if (!path.found) {
    return {
      phase: 'no-route',
      start,
      destination,
      routeMode: mode,
      path: null,
      directions: null,
      errorMessage: null,
    };
  }

  // Compute directions
  const directions = computeDirections(path, mode, graph);

  return {
    phase: 'ready',
    start,
    destination,
    routeMode: mode,
    path,
    directions,
    errorMessage: null,
  };
}

/**
 * Mobile port of src/client/hooks/useRouteSelection.ts.
 *
 * Changes from web version:
 * - `@shared/types` import replaced with relative `../../src/shared/types`
 * - RouteSelection interface inlined (no shared module dependency)
 */

import type { NavNode } from '../../src/shared/types';
import { useCallback, useMemo, useState } from 'react';

/* ──────────────── Types ──────────────── */

export interface RouteSelection {
  readonly start: NavNode | null;
  readonly destination: NavNode | null;
  readonly activeField: 'start' | 'destination';
  readonly bothSelected: boolean;
  readonly setStart: (node: NavNode | null) => void;
  readonly setDestination: (node: NavNode | null) => void;
  readonly setActiveField: (field: 'start' | 'destination') => void;
  /** Assigns a tapped node to the active field, auto-advancing to the other field. */
  readonly setFromTap: (node: NavNode) => void;
  /** Exchanges start and destination. No-op when both are null. */
  readonly swap: () => void;
  readonly clearStart: () => void;
  readonly clearDestination: () => void;
  readonly clearAll: () => void;
}

/* ──────────────── Hook ──────────────── */

/**
 * Manages route selection state — start (A) and destination (B) nodes.
 *
 * `setFromTap` assigns a tapped node to whichever field `activeField` points to,
 * auto-advancing to the other field afterward. If the tapped node is already the
 * OTHER field, it swaps them instead of duplicating.
 */
export function useRouteSelection(): RouteSelection {
  const [start, setStartState] = useState<NavNode | null>(null);
  const [destination, setDestinationState] = useState<NavNode | null>(null);
  const [activeField, setActiveField] = useState<'start' | 'destination'>('start');

  const setStart = useCallback((node: NavNode | null) => {
    setStartState(node);
    setActiveField('destination');
  }, []);

  const setDestination = useCallback((node: NavNode | null) => {
    setDestinationState(node);
    setActiveField('start');
  }, []);

  const setFromTap = useCallback(
    (node: NavNode) => {
      if (activeField === 'start') {
        // If tapped node is already the destination, swap start ↔ destination
        if (destination?.id === node.id) {
          setDestinationState(start);
          setStartState(node);
          setActiveField('destination');
        } else {
          setStartState(node);
          setActiveField('destination');
        }
      } else {
        // activeField === 'destination'
        // If tapped node is already the start, swap start ↔ destination
        if (start?.id === node.id) {
          setStartState(destination);
          setDestinationState(node);
          setActiveField('start');
        } else {
          setDestinationState(node);
          setActiveField('start');
        }
      }
    },
    [activeField, start, destination],
  );

  const swap = useCallback(() => {
    if (start === null && destination === null) return;
    const prevStart = start;
    const prevDest = destination;
    setStartState(prevDest);
    setDestinationState(prevStart);
  }, [start, destination]);

  const clearStart = useCallback(() => {
    setStartState(null);
    setActiveField('start');
  }, []);

  const clearDestination = useCallback(() => {
    setDestinationState(null);
    setActiveField('destination');
  }, []);

  const clearAll = useCallback(() => {
    setStartState(null);
    setDestinationState(null);
    setActiveField('start');
  }, []);

  const bothSelected = useMemo(
    () => start !== null && destination !== null,
    [start, destination],
  );

  return {
    start,
    destination,
    activeField,
    bothSelected,
    setStart,
    setDestination,
    setActiveField,
    setFromTap,
    swap,
    clearStart,
    clearDestination,
    clearAll,
  };
}

/**
 * Direction section grouping — groups direction steps by floor.
 *
 * Ported from src/client/components/directionSections.ts with corrected imports.
 */

import type { DirectionSection, DirectionStep } from '../domain/navGraph';

/**
 * Group contiguous direction steps by floor metadata.
 *
 * Notes:
 * - Grouping is boundary-based (contiguous runs), not global merge by floor.
 * - A later return to an earlier floor creates a new section.
 */
export function groupDirectionSections(steps: DirectionStep[]): DirectionSection[] {
  const sections: DirectionSection[] = [];

  for (const step of steps) {
    const lastSection = sections[sections.length - 1];

    if (
      lastSection !== undefined &&
      lastSection.floorId === step.floorId &&
      lastSection.floorNumber === step.floorNumber
    ) {
      lastSection.steps.push(step);
      continue;
    }

    sections.push({
      floorId: step.floorId,
      floorNumber: step.floorNumber,
      steps: [step],
    });
  }

  return sections;
}

/**
 * Direction step generation — pure function, no React dependencies.
 *
 * Ported from src/client/hooks/useRouteDirections.ts with corrected relative imports.
 * Used by mobile routing UI to convert computed paths into human-readable directions.
 */

import type { NavFloor, NavNode } from '../../src/shared/types';
import type { DirectionsResult, DirectionStep, PathResult, RouteMode, StepIcon } from '../domain/navGraph';

// ============================================================
// Constants
// ============================================================

const WALKING_SPEED_STANDARD = 0.023; // normalized units/s
const WALKING_SPEED_ACCESSIBLE = 0.013; // normalized units/s

/** Node types that are visible/searchable destinations — eligible for landmark references */
const LANDMARK_TYPES = new Set(['room', 'landmark', 'entrance', 'elevator', 'restroom']);

// ============================================================
// Private helpers
// ============================================================

/**
 * Compute compass bearing in degrees (0–360) from point A to point B.
 * Uses screen-space convention: x increases right, y increases down.
 * atan2(dx, -dy) gives a bearing where 0°=north, 90°=east, 180°=south, 270°=west.
 */
function bearing(ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax;
  const dy = by - ay;
  // atan2(x, -y) → clockwise from north in screen-space
  const rad = Math.atan2(dx, -dy);
  const deg = (rad * 180) / Math.PI;
  return (deg + 360) % 360;
}

/**
 * Normalize an angle difference to the range [-180, 180].
 */
function normalizeDelta(delta: number): number {
  let d = delta % 360;
  if (d > 180) d -= 360;
  if (d < -180) d += 360;
  return d;
}

/**
 * Euclidean distance between two normalized coordinate points.
 */
function euclideanDist(ax: number, ay: number, bx: number, by: number): number {
  const dx = bx - ax;
  const dy = by - ay;
  return Math.sqrt(dx * dx + dy * dy);
}

/**
 * Resolve a floor number from floor metadata, falling back to floorId when metadata is missing.
 */
function resolveFloorNumber(floorId: number, floorMap: Map<number, NavFloor>): number {
  return floorMap.get(floorId)?.floorNumber ?? floorId;
}

/**
 * Determine vertical movement direction between two floors.
 * Uses resolved floor numbers first; if tied, falls back to floorId to keep output deterministic.
 */
function getVerticalDirection(
  fromFloorId: number,
  toFloorId: number,
  floorMap: Map<number, NavFloor>,
): 'up' | 'down' {
  const fromFloorNumber = resolveFloorNumber(fromFloorId, floorMap);
  const toFloorNumber = resolveFloorNumber(toFloorId, floorMap);

  if (toFloorNumber > fromFloorNumber) return 'up';
  if (toFloorNumber < fromFloorNumber) return 'down';

  return toFloorId >= fromFloorId ? 'up' : 'down';
}

/**
 * Classify bearing delta into a step icon.
 */
function classifyTurn(
  delta: number,
): Exclude<StepIcon, 'arrive' | 'accessible' | 'stairs-up' | 'stairs-down' | 'elevator' | 'ramp'> {
  const abs = Math.abs(delta);
  if (abs < 30) return 'straight';
  if (abs < 120) return delta > 0 ? 'turn-right' : 'turn-left';
  return delta > 0 ? 'sharp-right' : 'sharp-left';
}

/**
 * Build the instruction text for a direction step at the current (middle) node.
 * Appends " at the {label}" when the node is a searchable landmark-type.
 */
function buildInstruction(
  icon: Exclude<StepIcon, 'accessible' | 'stairs-up' | 'stairs-down' | 'elevator' | 'ramp'>,
  node: NavNode,
): string {
  const base: Record<
    Exclude<StepIcon, 'accessible' | 'stairs-up' | 'stairs-down' | 'elevator' | 'ramp'>,
    string
  > = {
    straight: 'Continue straight',
    'turn-left': 'Turn left',
    'turn-right': 'Turn right',
    'sharp-left': 'Sharp left',
    'sharp-right': 'Sharp right',
    arrive: `Arrive at ${node.label}`,
  };

  const text = base[icon];

  // For non-arrive steps: append landmark reference if the node is a visible, searchable destination
  if (icon !== 'arrive' && LANDMARK_TYPES.has(node.type) && node.searchable) {
    return `${text} at the ${node.label}`;
  }

  return text;
}

// ============================================================
// Core function
// ============================================================

/**
 * Convert an ordered list of node IDs into turn-by-turn walking directions.
 *
 * Algorithm:
 * - 0 or 1 nodes → empty result
 * - 2 nodes → single "arrive" step (no turn to compute)
 * - N nodes → for each triple (prev, curr, next): classify bearing delta → build step
 *             then append final "arrive" step for the last node
 */
export function generateDirections(
  nodeIds: string[],
  nodeMap: Map<string, NavNode>,
  mode: RouteMode,
  floorMap: Map<number, NavFloor> = new Map(),
): DirectionsResult {
  if (nodeIds.length < 2) {
    return { steps: [], totalDistanceNorm: 0, totalDurationSec: 0 };
  }

  const speed = mode === 'accessible' ? WALKING_SPEED_ACCESSIBLE : WALKING_SPEED_STANDARD;
  const steps: DirectionStep[] = [];
  let totalDistanceNorm = 0;

  // Process intermediate nodes (all except the first and last)
  for (let i = 1; i < nodeIds.length - 1; i++) {
    const prevId = nodeIds[i - 1];
    const currId = nodeIds[i];
    const nextId = nodeIds[i + 1];

    const prev = nodeMap.get(prevId);
    const curr = nodeMap.get(currId);
    const next = nodeMap.get(nextId);
    if (prev === undefined || curr === undefined || next === undefined) continue;

    const distanceM = euclideanDist(prev.x, prev.y, curr.x, curr.y);
    const durationSec = distanceM / speed;
    const currFloorNumber = resolveFloorNumber(curr.floorId, floorMap);
    const nextFloorNumber = resolveFloorNumber(next.floorId, floorMap);

    // Floor-change detection: check if curr→next crosses a floor boundary
    if (curr.floorId !== next.floorId) {
      const verticalDirection = getVerticalDirection(curr.floorId, next.floorId, floorMap);

      // Determine direction icon based on connector type and vertical direction
      let icon: StepIcon;
      if (curr.type === 'stairs') {
        icon = verticalDirection === 'up' ? 'stairs-up' : 'stairs-down';
      } else if (curr.type === 'elevator') {
        icon = 'elevator';
      } else if (curr.type === 'ramp') {
        icon = 'ramp';
      } else {
        // Fallback: should not occur in a well-formed graph
        icon = verticalDirection === 'up' ? 'stairs-up' : 'stairs-down';
      }

      // Determine connector type name for instruction text
      const connectorTypeName =
        curr.type === 'elevator' ? 'elevator' : curr.type === 'ramp' ? 'ramp' : 'stairs';

      const instruction = `Take the ${connectorTypeName} ${verticalDirection} to Floor ${nextFloorNumber}`;
      const isAccessibleSegment = curr.type === 'elevator' || curr.type === 'ramp';

      steps.push({
        instruction,
        icon,
        distanceM,
        durationSec,
        isAccessibleSegment,
        floorId: curr.floorId,
        floorNumber: currFloorNumber,
      });
      totalDistanceNorm += distanceM;
      continue;
    }

    const inBearing = bearing(prev.x, prev.y, curr.x, curr.y);
    const outBearing = bearing(curr.x, curr.y, next.x, next.y);
    const delta = normalizeDelta(outBearing - inBearing);

    const icon = classifyTurn(delta);
    const instruction = buildInstruction(icon, curr);
    const isAccessibleSegment = curr.type === 'ramp' || curr.type === 'elevator';

    steps.push({
      instruction,
      icon,
      distanceM,
      durationSec,
      isAccessibleSegment,
      floorId: curr.floorId,
      floorNumber: currFloorNumber,
    });
    totalDistanceNorm += distanceM;
  }

  // Final "arrive" step — distance from second-to-last to last node
  const lastPrevId = nodeIds[nodeIds.length - 2];
  const lastId = nodeIds[nodeIds.length - 1];
  const lastPrev = nodeMap.get(lastPrevId);
  const last = nodeMap.get(lastId);
  if (lastPrev === undefined || last === undefined) {
    return { steps: [], totalDistanceNorm: 0, totalDurationSec: 0 };
  }

  const arriveDistance = euclideanDist(lastPrev.x, lastPrev.y, last.x, last.y);
  const arriveDuration = arriveDistance / speed;
  const arriveInstruction = buildInstruction('arrive', last);

  steps.push({
    instruction: arriveInstruction,
    icon: 'arrive',
    distanceM: arriveDistance,
    durationSec: arriveDuration,
    isAccessibleSegment: last.type === 'ramp' || last.type === 'elevator',
    floorId: last.floorId,
    floorNumber: resolveFloorNumber(last.floorId, floorMap),
  });

  totalDistanceNorm += arriveDistance;
  const totalDurationSec = steps.reduce((sum, s) => sum + s.durationSec, 0);

  return { steps, totalDistanceNorm, totalDurationSec };
}

// ============================================================
// routesAreIdentical utility
// ============================================================

/**
 * Returns true only if both routes were found and share the exact same ordered node IDs.
 */
export function routesAreIdentical(a: PathResult, b: PathResult): boolean {
  if (!a.found || !b.found) return false;
  if (a.nodeIds.length !== b.nodeIds.length) return false;
  return a.nodeIds.every((id, i) => id === b.nodeIds[i]);
}

/**
 * GPS + heading subscription hook.
 *
 * Wraps navigator.geolocation.watchPosition and an optional magnetometer reader
 * behind thin interfaces so both are injectable for unit testing.
 *
 * Returns:
 * - position: latest GPS fix (null until first reading)
 * - heading: raw magnetometer reading (null until available)
 * - smoothedHeadingDegrees: EMA-smoothed heading (0–360, null until first reading)
 * - isConfident: true when accuracy ≤ maxAccuracyMeters (from isGpsFixConfident)
 * - isHeadingValid: true when magnetometer is available AND accuracyDegrees ≤ 15
 */

import { useEffect, useRef, useState } from 'react';
import { isGpsFixConfident } from '../../src/shared/gps';

/* ──────────────── Types ──────────────── */

/**
 * A single GPS position fix.
 * headingDegrees may be null when the device does not provide it.
 */
export interface PositionFix {
  latitude: number;
  longitude: number;
  accuracyMeters: number;
  headingDegrees: number | null;
  timestamp: number;
}

/**
 * A single magnetometer/compass reading.
 * headingDegrees is 0–360 clockwise from magnetic north.
 * accuracyDegrees estimates heading precision.
 */
export interface HeadingData {
  headingDegrees: number;
  accuracyDegrees: number;
}

/**
 * Abstracts the device magnetometer / compass API.
 * Start/stop lifecycle so the hook controls when the sensor is active.
 */
export interface HeadingReader {
  start(callback: (data: HeadingData) => void): void;
  stop(): void;
}

/**
 * Abstracts navigator.geolocation.watchPosition.
 * Returns a stop handle so the hook can tear down the watcher on unmount.
 */
export interface PositionReader {
  watchPosition(
    onPosition: (fix: PositionFix) => void,
    onError: (error: Error) => void,
  ): { stop: () => void };
}

/* ──────────────── Hook options ──────────────── */

export interface UseCurrentPositionOptions {
  /** Minimum interval between position updates in ms. Default: 2000. */
  updateIntervalMs?: number;
  /** Maximum accuracy (metres) for isConfident. Default: 50. */
  maxAccuracyMeters?: number;
  /** Heading source. Defaults to DefaultNativeHeadingReader. */
  headingReader?: HeadingReader;
  /** Position source. Defaults to DefaultPositionReader. */
  positionReader?: PositionReader;
}

/* ──────────────── Default readers ──────────────── */

/**
 * Default heading reader using the expo-sensors Magnetometer API.
 * Falls back to a no-op if the module is unavailable (e.g. web / no sensor).
 * Maps magnetometer X/Y magnitude to a heading in degrees.
 */
export class DefaultNativeHeadingReader implements HeadingReader {
  private subscription: { remove: () => void } | null = null;

  start(callback: (data: HeadingData) => void): void {
    this.stop();
    try {
      // Dynamic import so this file still compiles without expo-sensors installed.
      // eslint-disable-next-line @typescript-eslint/no-var-requires
      const { Magnetometer } = require('expo-sensors') as {
        Magnetometer: { addListener: (cb: (e: { x: number; y: number }) => void) => { remove: () => void } };
      };
      this.subscription = Magnetometer.addListener((event) => {
        // atan2(y, x) gives angle from magnetic north in radians; + math.PI/2 rotates
        // so 0° points magnetic north, then convert to degrees and normalise 0–360.
        const radians = Math.atan2(event.x, event.y);
        let degrees = ((radians * 180) / Math.PI + 90 + 360) % 360;
        callback({ headingDegrees: degrees, accuracyDegrees: 10 });
      });
    } catch {
      // expo-sensors not available — heading stays null.
    }
  }

  stop(): void {
    this.subscription?.remove();
    this.subscription = null;
  }
}

/**
 * Default position reader using navigator.geolocation.watchPosition.
 * Works in any browser or React Native environment with the Geolocation API.
 */
export class DefaultPositionReader implements PositionReader {
  watchPosition(
    onPosition: (fix: PositionFix) => void,
    onError: (error: Error) => void,
  ): { stop: () => void } {
    let watchId: number;

    const onGeoSuccess = (pos: GeolocationPosition) => {
      onPosition({
        latitude: pos.coords.latitude,
        longitude: pos.coords.longitude,
        accuracyMeters: pos.coords.accuracy ?? Infinity,
        headingDegrees: pos.coords.heading ?? null,
        timestamp: pos.timestamp,
      });
    };

    const onGeoError = (err: GeolocationPositionError) => {
      onError(new Error(`[Geolocation] ${err.message}`));
    };

    watchId = navigator.geolocation.watchPosition(onGeoSuccess, onGeoError, {
      enableHighAccuracy: true,
    });

    return {
      stop() {
        navigator.geolocation.clearWatch(watchId);
      },
    };
  }
}

/* ──────────────── Hook ──────────────── */

export interface UseCurrentPositionReturn {
  position: PositionFix | null;
  heading: HeadingData | null;
  /** EMA-smoothed heading in degrees (0–360). Null until first reading. */
  smoothedHeadingDegrees: number | null;
  isConfident: boolean;
  isHeadingValid: boolean;
}

/**
 * EMA smoothing factor applied per heading update.
 * Higher alpha → faster convergence to new reading.
 */
const HEADING_EMA_ALPHA = 0.3;

/**
 * Maximum magnetometer accuracy (degrees) to trust the heading.
 * Readings with worse accuracy are treated as invalid.
 */
const HEADING_ACCURACY_THRESHOLD_DEG = 15;

/**
 * Subscribes to device position and (optionally) magnetometer heading.
 *
 * Heading EMA handles wraparound at 0°/360° by always moving through the
 * shorter angular path toward the new reading.
 */
export function useCurrentPosition(
  options: UseCurrentPositionOptions = {},
): UseCurrentPositionReturn {
  const {
    maxAccuracyMeters = 50,
    headingReader = new DefaultNativeHeadingReader(),
    positionReader = new DefaultPositionReader(),
  } = options;

  const [position, setPosition] = useState<PositionFix | null>(null);
  const [heading, setHeading] = useState<HeadingData | null>(null);
  const [smoothedHeadingDegrees, setSmoothedHeadingDegrees] = useState<number | null>(null);
  const [isHeadingValid, setIsHeadingValid] = useState(false);

  // Keep the current smoothed heading in a ref so we don't need to re-subscribe
  // on every EMA update.
  const smoothedHeadingRef = useRef<number | null>(null);

  // True once at least one position fix has been received.
  const hasPosition = useRef(false);

  useEffect(() => {
    // ── Position subscription ────────────────────────────────────────────────
    const posHandle = positionReader.watchPosition(
      (fix) => {
        hasPosition.current = true;
        setPosition(fix);
      },
      // Non-fatal: keep the last known position rather than resetting to null.
      () => {},
    );

    // ── Heading subscription ────────────────────────────────────────────────
    headingReader.start((data) => {
      setHeading(data);
      const isValid = data.accuracyDegrees <= HEADING_ACCURACY_THRESHOLD_DEG;
      setIsHeadingValid(isValid);

      if (!isValid) return;

      const raw = data.headingDegrees;
      const current = smoothedHeadingRef.current;

      if (current === null) {
        // First valid reading — no smoothing needed.
        smoothedHeadingRef.current = raw;
        setSmoothedHeadingDegrees(raw);
        return;
      }

      // Compute shortest angular distance from current to new reading.
      let delta = raw - current;
      if (delta > 180) delta -= 360;
      if (delta < -180) delta += 360;

      const smoothed = current + HEADING_EMA_ALPHA * delta;
      // Normalise to 0–360.
      const normalised = ((smoothed % 360) + 360) % 360;

      smoothedHeadingRef.current = normalised;
      setSmoothedHeadingDegrees(normalised);
    });

    return () => {
      posHandle.stop();
      headingReader.stop();
    };
  }, [positionReader, headingReader]); // stable object references — no re-mount on render

  const isConfident = hasPosition.current
    ? position !== null && isGpsFixConfident(position.accuracyMeters, maxAccuracyMeters)
    : false;

  return {
    position,
    heading,
    smoothedHeadingDegrees,
    isConfident,
    isHeadingValid,
  };
}

import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Image,
  PanResponder,
  Pressable,
  StyleSheet,
  Text,
  View,
  type LayoutChangeEvent,
  type PanResponderInstance,
} from 'react-native';

import {
  applyPanDelta,
  applyPinchRotate,
  createInitialMapTransform,
  mapTransformsEqual,
  type MapTransform,
  type ViewportDimensions,
  type ViewportPoint,
} from './mapTransform';

interface MapViewportProps {
  imageUri: string;
  onTransformChange?: (transform: MapTransform) => void;
}

interface GestureTracking {
  mode: 'none' | 'pan' | 'pinch';
  lastPanPoint: ViewportPoint | null;
  pinchStartDistance: number;
  pinchStartAngle: number;
  pinchStartTransform: MapTransform;
}

function touchPoint(touch: { locationX: number; locationY: number }): ViewportPoint {
  return {
    x: touch.locationX,
    y: touch.locationY,
  };
}

function distance(a: ViewportPoint, b: ViewportPoint): number {
  return Math.hypot(b.x - a.x, b.y - a.y);
}

function angle(a: ViewportPoint, b: ViewportPoint): number {
  return Math.atan2(b.y - a.y, b.x - a.x);
}

function midpoint(a: ViewportPoint, b: ViewportPoint): ViewportPoint {
  return {
    x: (a.x + b.x) / 2,
    y: (a.y + b.y) / 2,
  };
}

function formatTransformValue(value: number): string {
  if (!Number.isFinite(value)) {
    return '0';
  }

  return value.toFixed(2);
}

export function MapViewport({ imageUri, onTransformChange }: MapViewportProps) {
  const [viewport, setViewport] = useState<ViewportDimensions | null>(null);
  const [transform, setTransform] = useState<MapTransform>(createInitialMapTransform);

  const gesture = useRef<GestureTracking>({
    mode: 'none',
    lastPanPoint: null,
    pinchStartDistance: 0,
    pinchStartAngle: 0,
    pinchStartTransform: createInitialMapTransform(),
  });

  useEffect(() => {
    onTransformChange?.(transform);
  }, [onTransformChange, transform]);

  const commitTransform = useCallback((updater: (current: MapTransform) => MapTransform) => {
    setTransform((current) => {
      const next = updater(current);
      return mapTransformsEqual(current, next) ? current : next;
    });
  }, []);

  const panResponder: PanResponderInstance = useMemo(
    () =>
      PanResponder.create({
        onStartShouldSetPanResponder: () => true,
        onMoveShouldSetPanResponder: () => true,
        onPanResponderGrant: (event) => {
          const touches = event.nativeEvent.touches;

          if (touches.length >= 2) {
            const first = touches[0];
            const second = touches[1];
            if (!first || !second) {
              return;
            }

            const a = touchPoint(first);
            const b = touchPoint(second);
            gesture.current.mode = 'pinch';
            gesture.current.pinchStartDistance = distance(a, b);
            gesture.current.pinchStartAngle = angle(a, b);
            gesture.current.pinchStartTransform = transform;
            gesture.current.lastPanPoint = null;
            return;
          }

          const first = touches[0];
          if (!first) {
            return;
          }

          gesture.current.mode = 'pan';
          gesture.current.lastPanPoint = touchPoint(first);
        },
        onPanResponderMove: (event) => {
          const touches = event.nativeEvent.touches;

          if (touches.length >= 2) {
            const first = touches[0];
            const second = touches[1];
            if (!first || !second) {
              return;
            }

            const firstPoint = touchPoint(first);
            const secondPoint = touchPoint(second);

            if (gesture.current.mode !== 'pinch' || gesture.current.pinchStartDistance <= 0) {
              gesture.current.mode = 'pinch';
              gesture.current.pinchStartDistance = distance(firstPoint, secondPoint);
              gesture.current.pinchStartAngle = angle(firstPoint, secondPoint);
              gesture.current.pinchStartTransform = transform;
              gesture.current.lastPanPoint = null;
              return;
            }

            const currentDistance = distance(firstPoint, secondPoint);
            const currentAngle = angle(firstPoint, secondPoint);
            if (!Number.isFinite(currentDistance) || currentDistance <= 0 || !Number.isFinite(currentAngle)) {
              return;
            }

            const scaleFactor = currentDistance / gesture.current.pinchStartDistance;
            const rotationDeltaDeg = ((currentAngle - gesture.current.pinchStartAngle) * 180) / Math.PI;
            const focal = midpoint(firstPoint, secondPoint);

            commitTransform(() =>
              applyPinchRotate(gesture.current.pinchStartTransform, {
                scaleFactor,
                rotationDeltaDeg,
                focal,
                viewport,
              }),
            );

            return;
          }

          if (touches.length === 1) {
            const touch = touches[0];
            if (!touch) {
              return;
            }

            const point = touchPoint(touch);

            if (gesture.current.mode !== 'pan' || !gesture.current.lastPanPoint) {
              gesture.current.mode = 'pan';
              gesture.current.lastPanPoint = point;
              return;
            }

            const delta = {
              x: point.x - gesture.current.lastPanPoint.x,
              y: point.y - gesture.current.lastPanPoint.y,
            };

            commitTransform((current) => applyPanDelta(current, delta));
            gesture.current.lastPanPoint = point;
            return;
          }

          gesture.current.mode = 'none';
          gesture.current.lastPanPoint = null;
        },
        onPanResponderRelease: () => {
          gesture.current.mode = 'none';
          gesture.current.lastPanPoint = null;
          gesture.current.pinchStartDistance = 0;
        },
        onPanResponderTerminate: () => {
          gesture.current.mode = 'none';
          gesture.current.lastPanPoint = null;
          gesture.current.pinchStartDistance = 0;
        },
      }),
    [commitTransform, transform, viewport],
  );

  const onLayout = (event: LayoutChangeEvent) => {
    const { width, height } = event.nativeEvent.layout;
    if (width <= 0 || height <= 0) {
      return;
    }

    setViewport({ width, height });
  };

  const applyScaleAtViewportCenter = (scaleFactor: number) => {
    commitTransform((current) =>
      applyPinchRotate(current, {
        scaleFactor,
        rotationDeltaDeg: 0,
        focal: {
          x: viewport ? viewport.width / 2 : 0,
          y: viewport ? viewport.height / 2 : 0,
        },
        viewport,
      }),
    );
  };

  const applyRotationAtViewportCenter = (rotationDeltaDeg: number) => {
    commitTransform((current) =>
      applyPinchRotate(current, {
        scaleFactor: 1,
        rotationDeltaDeg,
        focal: {
          x: viewport ? viewport.width / 2 : 0,
          y: viewport ? viewport.height / 2 : 0,
        },
        viewport,
      }),
    );
  };

  return (
    <View style={styles.container}>
      <View style={styles.controls}>
        <Pressable onPress={() => applyScaleAtViewportCenter(1.2)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Zoom +</Text>
        </Pressable>
        <Pressable onPress={() => applyScaleAtViewportCenter(1 / 1.2)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Zoom -</Text>
        </Pressable>
        <Pressable onPress={() => applyRotationAtViewportCenter(-15)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Rotate ↺</Text>
        </Pressable>
        <Pressable onPress={() => applyRotationAtViewportCenter(15)} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Rotate ↻</Text>
        </Pressable>
        <Pressable onPress={() => setTransform(createInitialMapTransform())} style={styles.controlButton}>
          <Text style={styles.controlButtonText}>Reset</Text>
        </Pressable>
      </View>

      <View style={styles.viewport} onLayout={onLayout} {...panResponder.panHandlers}>
        <Image
          source={{ uri: imageUri }}
          resizeMode="contain"
          style={[
            styles.mapImage,
            {
              transform: [
                { translateX: transform.translation.x },
                { translateY: transform.translation.y },
                { rotateZ: `${transform.rotationDeg}deg` },
                { scale: transform.scale },
              ],
            },
          ]}
        />
      </View>

      <Text style={styles.telemetry}>
        scale={formatTransformValue(transform.scale)} rotation={formatTransformValue(transform.rotationDeg)}° tx=
        {formatTransformValue(transform.translation.x)} ty={formatTransformValue(transform.translation.y)}
      </Text>
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    width: '100%',
    flex: 1,
    gap: 8,
  },
  controls: {
    flexDirection: 'row',
    flexWrap: 'wrap',
    gap: 6,
  },
  controlButton: {
    backgroundColor: '#0f172a',
